window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[193]={"id":"193","numero":193,"titre":"Vascularites systémiques","objectifs":[{"id":"193-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une vascularite systémique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types de vascularites systémiques","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes évocateurs du diagnostic de vascularite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":7},{"id":"193-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels à évoquer en cas de suspicion de vascularite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les organes cibles et les moyens diagnostiques","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"193-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques d’un purpura vasculaire","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-7","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un purpura vasculaire","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens à réaliser en cas de suspicion de vascularite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"193-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens immunologiques à réaliser en cas de suspicion de vascularite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"193-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge des vascularites","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"193-11","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principaux facteurs pronostiques des vascularites","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-14-0.php","label":"lecofer.org"},{"href":"https://radiopaedia.org/articles/revised-international-chapel-hill-consensus-conference-nomenclature-of-vasculitides","label":"radiopaedia.org"},{"href":"https://www.maladies-vasculaires-rares.fr/maladie-de-buerger","label":"maladies-vasculaires-rares.fr"},{"href":"https://radiopaedia.org/articles/anti-neutrophil-cytoplasmic-antibody-associated-vasculitides","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/antineutrophil-cytoplasmic-antibody","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/granulomatosis-with-polyangiitis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/eosinophilic-granulomatosis-with-polyangiitis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/microscopic-polyangiitis","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Vascularite suspectée : mécanisme (ANCA pauci-immun vs complexes immuns) ? — Orienter par ANCA, complément et cryoglobulines (petits vaisseaux ++)","detail":"<h4>CAT — orientation diagnostique devant une <span class=\"kw-clinique\">vascularite</span> suspectée — Tri par le mécanisme : <span class=\"kw-bio\">ANCA</span> pauci-immun <span class=\"kw-bio\">vs</span> complexes immuns <span class=\"kw-bio\">vs</span> moyen calibre</h4>","branches":[{"to":"q-phenotype","label":"ANCA positifs (PR3 / MPO) — pauci-immune, sans dépôt","color":"red"},{"to":"q-depots","label":"ANCA négatifs — dépôts de complexes immuns (IF +)","color":"amber"},{"to":"t-pan","label":"ANCA négatifs, sans dépôt immun — moyen calibre (microanévrysmes)","color":"amber"}]},{"id":"q-phenotype","kind":"decision","label":"Phénotype clinico-immunologique ? — c-ANCA/PR3 vs p-ANCA/MPO · organes cibles dominants","branches":[{"to":"t-gpa","label":"c-ANCA / PR3 — ORL destructeur + nodules excavés + GNRP","color":"red"},{"to":"t-gepa","label":"p-ANCA / MPO — asthme + hyperéosinophilie","color":"amber"},{"to":"t-mpa","label":"p-ANCA / MPO — GNRP + hémorragie alvéolaire, sans granulome","color":"red"}]},{"id":"t-gpa","kind":"terminal","label":"GPA — granulomatose avec polyangéite (Wegener)","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">c-ANCA</span> de spécificité <span class=\"kw-bio\">PR3</span> (<span class=\"kw-chiffre\">&gt; 90 %</span> des cas) ; <span class=\"kw-bio\">histologie</span> = <span class=\"kw-bio\">granulome à cellules géantes</span> + <span class=\"kw-bio\">nécrose fibrinoïde</span> (<span class=\"kw-ttt\">biopsie</span> de muqueuse nasale, PBR, biopsie pulmonaire)</li></ul><h4>Atteintes évocatrices</h4><ul><li><span class=\"kw-clinique\">ORL destructeur</span> : rhinite croûteuse et ulcérée, épistaxis, sinusite, otite, ulcérations pharyngées, tumeur rétro-orbitaire</li><li><span class=\"kw-clinique\">Poumon</span> : nodules multiples parfois <span class=\"kw-imagerie\">excavés</span>, <span class=\"kw-clinique\">hémoptysie</span></li><li><span class=\"kw-alerte\">GNRP de type 3</span> (absence de dépôt) → <span class=\"kw-alerte\">IRA en quelques jours</span>, PBR urgente</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> + <span class=\"kw-ttt\">cyclophosphamide</span> ou <span class=\"kw-ttt\">rituximab</span> en induction, puis entretien (<span class=\"kw-ttt\">rituximab</span>, <span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">méthotrexate</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 261 (néphropathie glomérulaire)</li></ul>"},{"id":"t-gepa","kind":"terminal","label":"GEPA — granulomatose éosinophilique avec polyangéite (Churg-Strauss)","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">p-ANCA</span> de spécificité <span class=\"kw-bio\">MPO</span> (<span class=\"kw-chiffre\">~30-40 %</span> des cas) ; <span class=\"kw-bio\">hyperéosinophilie sanguine</span> (<span class=\"kw-chiffre\">&gt; 0,5 G/L</span>) et tissulaire (<span class=\"kw-bio\">LBA</span>) ; <span class=\"kw-bio\">histologie</span> = granulome + <span class=\"kw-clinique\">nécrose</span> fibrinoïde + nombreux <span class=\"kw-bio\">PNE</span></li></ul><h4>Atteintes évocatrices</h4><ul><li><span class=\"kw-clinique\">Asthme</span> constant, de révélation tardive, souvent sévère et corticodépendant</li><li><span class=\"kw-clinique\">Polypose nasale</span> ; pneumopathie à <span class=\"kw-bio\">éosinophiles</span> (« <span class=\"kw-alerte\">OAP</span> inversé »)</li><li><span class=\"kw-alerte\">Cardiomyopathie éosinophilique</span> : souvent grave, conditionne le <span class=\"kw-def\">pronostic</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> ± <span class=\"kw-ttt\">immunosuppresseur</span> selon la sévérité (Five Factor <span class=\"kw-def\">Score</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 218 (éosinophilie)</li></ul>"},{"id":"t-mpa","kind":"terminal","label":"MPA — polyangéite microscopique","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">p-ANCA</span> de spécificité <span class=\"kw-bio\">MPO</span> (<span class=\"kw-chiffre\">&gt; 75-80 %</span> des cas) ; <span class=\"kw-bio\">histologie</span> = <span class=\"kw-bio\">nécrose fibrinoïde</span> SANS granulome</li></ul><h4>Atteintes évocatrices</h4><ul><li><span class=\"kw-alerte\">GNRP de type 3</span> (absence de dépôt) → <span class=\"kw-alerte\">IRA en quelques jours</span>, PBR urgente</li><li><span class=\"kw-alerte\">Hémorragie alvéolaire</span> par capillarite nécrosante (<span class=\"kw-def\">syndrome pneumo-rénal</span>)</li><li><span class=\"kw-clinique\">Purpura vasculaire</span>, multinévrite</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> + <span class=\"kw-ttt\">cyclophosphamide</span> ou <span class=\"kw-ttt\">rituximab</span> ; <span class=\"kw-ttt\">échanges plasmatiques</span> si <span class=\"kw-ci\">insuffisance rénale</span> sévère ou hémorragie alvéolaire</li></ul><h4>Renvoi</h4><ul><li>Item 261 (néphropathie glomérulaire)</li></ul>"},{"id":"q-depots","kind":"decision","label":"Type de dépôt / contexte ? — IgA de l'enfant vs cryoglobulines (VHC)","branches":[{"to":"t-pr","label":"Dépôts d'IgA — enfant, triade purpura/arthralgies/douleurs abdo","color":"green"},{"to":"t-cryo","label":"Cryoglobulines (VHC ++) — purpura + Raynaud + neuropathie","color":"amber"}]},{"id":"t-pr","kind":"terminal","label":"Purpura rhumatoïde (vascularite à IgA)","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Vascularite</span> à dépôts de complexes immuns à <span class=\"kw-bio\">IgA</span> — la plus fréquente de l'enfant (garçon, âge <span class=\"kw-chiffre\">≤ 8 ans</span>)</li></ul><h4>Clinique</h4><ul><li>Triade : <span class=\"kw-clinique\">purpura vasculaire</span> déclive (constant) + <span class=\"kw-clinique\">arthralgies</span> + <span class=\"kw-clinique\">douleurs abdominales</span>, sur fond de <span class=\"kw-clinique\">fièvre</span> modérée</li><li><span class=\"kw-bio\">Plaquettes normales</span> ; <span class=\"kw-bio\">BU</span> + <span class=\"kw-bio\">créatininémie</span>/<span class=\"kw-bio\">DFG</span> systématiques (<span class=\"kw-def\">dépistage</span> de la néphropathie à <span class=\"kw-chiffre\">IgA</span>, ~1/3 des cas)</li></ul><h4>Conduite</h4><ul><li>PEC <span class=\"kw-ttt\">ambulatoire symptomatique</span> (<span class=\"kw-ttt\">antalgiques</span>, <span class=\"kw-ttt\">antispasmodiques</span>) ; <span class=\"kw-ttt\">corticoïdes</span> réservés aux complications sévères ; le repos est sans effet sur le <span class=\"kw-def\">pronostic</span></li></ul><h4><span class=\"kw-alerte\">Red flags</span></h4><ul><li><span class=\"kw-alerte\">Invagination intestinale aiguë</span>, <span class=\"kw-alerte\">perforation ou hémorragie digestive</span>, <span class=\"kw-alerte\">orchite</span> — peuvent être inaugurales</li></ul><h4>Renvoi</h4><ul><li>Item 215 (<span class=\"kw-clinique\">purpura</span>)</li></ul>"},{"id":"t-cryo","kind":"terminal","label":"Vascularite cryoglobulinémique","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Cryoglobulines</span> + typage (<span class=\"kw-def\">type 2 mixte</span> = <span class=\"kw-etio\">VHC</span> dans <span class=\"kw-chiffre\">70-90 %</span> des cas) ; <span class=\"kw-bio\">complément C3/C4/CH50</span> souvent consommé ; <span class=\"kw-bio\">ANCA négatifs</span></li></ul><h4>Atteintes évocatrices</h4><ul><li><span class=\"kw-clinique\">Purpura vasculaire</span>, <span class=\"kw-clinique\">syndrome de Raynaud</span>, arthralgies</li><li><span class=\"kw-clinique\">Neuropathie périphérique</span> ; glomérulonéphrite membrano-proliférative</li></ul><h4>Traitement</h4><ul><li>Traiter la <span class=\"kw-etio\">cause</span> (<span class=\"kw-etio\">VHC</span>, hémopathie lymphoïde) ; <span class=\"kw-ttt\">rituximab</span> si forme sévère ou échec du traitement <span class=\"kw-ttt\">antiviral</span></li></ul><h4>Renvoi</h4><ul><li>Item 167 (hépatites virales)</li></ul>"},{"id":"t-pan","kind":"terminal","label":"Périartérite noueuse (PAN)","color":"amber","detail":"<h4>Définition</h4><ul><li>Angéite <span class=\"kw-def\">nécrosante</span> des artères de <span class=\"kw-def\">moyen calibre</span> : <span class=\"kw-imagerie\">microanévrysmes</span> + occlusions / <span class=\"kw-clinique\">infarctus</span> tissulaires ; <span class=\"kw-bio\">ANCA négatifs</span></li></ul><h4>Étiologie</h4><ul><li>Idiopathique ou liée à une <span class=\"kw-etio\">hépatite B</span> (recherche systématique)</li></ul><h4>Atteintes évocatrices</h4><ul><li><span class=\"kw-clinique\">Multinévrite</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, nodules / <span class=\"kw-clinique\">livedo</span></li><li>Atteinte rénale <span class=\"kw-def\">vasculaire</span> : microanévrysmes intrarénaux, <span class=\"kw-clinique\">infarctus</span>, <span class=\"kw-clinique\">HTA</span>, IR — SANS syndrome glomérulaire</li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">PBR contre-indiquée</span> (risque <span class=\"kw-alerte\">hémorragique</span> sur <span class=\"kw-clinique\">les</span> microanévrysmes intra-parenchymateux)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticoïdes</span> ± <span class=\"kw-ttt\">immunosuppresseur</span> ; <span class=\"kw-ttt\">échanges plasmatiques</span> + <span class=\"kw-ttt\">antiviral</span> dans la PAN liée au <span class=\"kw-etio\">VHB</span></li></ul><h4>Renvoi</h4><ul><li>Item 167 (hépatites virales)</li></ul>"}]},"cards":[{"i":"49c6995c7498","n":193,"o":"193-1","u":"Définition","t":"Connaître la définition d’une vascularite systémique","q":"Quelles sont les conséquences cliniques de l'inflammation vasculaire dans le cadre des vascularites systémiques ?","a":"<p>L'inflammation vasculaire peut entraîner des lésions de la paroi du vaisseau, comme une <strong>nécrose fibrinoïde</strong>, un <strong>épaississement</strong> ou une <strong>thrombose</strong>. Ces lésions peuvent conduire à une <strong>ischémie tissulaire</strong> en aval ou à une <strong>rupture vasculaire</strong> avec hémorragie.</p>"},{"i":"dd1940ab755e","n":193,"o":"193-1","u":"Définition","t":"Connaître la définition d’une vascularite systémique","q":"Quelle est la définition générale d'une vascularite systémique ?","a":"<p>Une vascularite systémique est une inflammation de la paroi des vaisseaux sanguins. Cette inflammation peut toucher les artères, les veinules ou les capillaires, de tout calibre et de n'importe quel organe.</p>"},{"i":"09c883b5d20a","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quelles atteintes rénales sont évocatrices d'une vascularite systémique ?","a":"<p>Les atteintes rénales évocatrices sont une <strong>glomérulonéphrite rapidement progressive</strong> (GNRP), souvent associée à une hématurie microscopique et une protéinurie, pouvant évoluer vers une insuffisance rénale aiguë.</p>"},{"i":"32418b881a7b","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quels signes pulmonaires peuvent faire suspecter une vascularite systémique ?","a":"<p>Les signes pulmonaires peuvent inclure une <strong>hémorragie alvéolaire</strong> (se manifestant par une hémoptysie et des infiltrats pulmonaires bilatéraux diffus), une <strong>asthme tardif ou corticodépendant</strong>, des <strong>nodules pulmonaires</strong> ou une <strong>fibrose pulmonaire</strong>.</p>"},{"i":"3d86944e9977","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quelles atteintes neurologiques faut-il rechercher en cas de suspicion de vascularite systémique ?","a":"<p>Les atteintes neurologiques à rechercher sont principalement une <strong>mononévrite multiple</strong> (atteinte asymétrique et multifocale des nerfs périphériques), ou plus rarement une <strong>polynévrite</strong> symétrique ou une <strong>atteinte du système nerveux central</strong> (AVC, encéphalopathie).</p>"},{"i":"73a7cb89f482","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quelles anomalies biologiques non spécifiques sont généralement présentes en cas de vascularite systémique ?","a":"<p>On retrouve fréquemment un <strong>syndrome inflammatoire biologique</strong> avec augmentation de la <strong>CRP</strong> (C-réactive protéine) et de la <strong>VS</strong> (vitesse de sédimentation) ainsi qu'une <strong>anémie inflammatoire</strong>.</p>"},{"i":"bb15f9eb29b7","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quel type d'atteinte cutanée est particulièrement évocateur d'une vascularite systémique, notamment des petites et moyennes artères ?","a":"<p>Une <strong>purpura vasculaire (ou pétéchial ou palpable)</strong> est très évocatrice d'une vascularite systémique, en particulier des petites et moyennes artères. Des <strong>ulcérations</strong> ou des <strong>livedo réticularis</strong> peuvent aussi être observés.</p>"},{"i":"f974d283248a","n":193,"o":"193-3","u":"Diagnostic positif","t":"Connaître les principaux signes évocateurs du diagnostic de vascularite","q":"Quels sont les trois grands cadres cliniques évocateurs d'une vascularite systémique à rechercher au début du diagnostic ?","a":"<p>Les trois grands cadres cliniques évocateurs d'une vascularite sont :</p><ul><li>Un syndrome <strong>inflammatoire inexpliqué</strong>.</li><li>Des signes <strong>généraux inexpliqués</strong>.</li><li>Des <strong>atteintes d'organes multiples</strong>.</li></ul>"},{"i":"356848ccb278","n":193,"o":"193-6","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura vasculaire","q":"Quels sont les signes associés au purpura vasculaire qui peuvent suggérer une atteinte systémique dans le cadre d'une vascularite ?","a":"<ul><li>Des signes généraux : <strong>fièvre</strong>, altération de l'état général (asthénie, anorexie, perte de poids).</li><li>Des <strong>arthralgies</strong> ou des arthrites.</li><li>Une atteinte rénale (hématurie, protéinurie).</li><li>Une atteinte neurologique (neuropathie périphérique, AVC).</li><li>Une atteinte digestive (douleurs abdominales, hémorragies).</li><li>Une atteinte pulmonaire (hémoptysie, dyspnée).</li></ul>"},{"i":"8b35e3063a85","n":193,"o":"193-6","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura vasculaire","q":"Quelles sont les caractéristiques morphologiques d'un purpura vasculaire qui orientent vers sa nature inflammatoire ?","a":"<ul><li>Le caractère <strong>palpable</strong> des lésions.</li><li>La présence de <strong>lésions nécrotiques</strong> ou ulcérées.</li><li>Des signes d'<strong>inflammation locale</strong> comme l'œdème ou l'érythème autour des lésions.</li><li>Une distribution généralement <strong>symétrique</strong> et déclive, mais les lésions peuvent atteindre toutes les zones cutanées.</li></ul>"},{"i":"e8a7f90fc221","n":193,"o":"193-6","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura vasculaire","q":"Quelle est la définition clinique d'un purpura vasculaire ?","a":"<p>Un purpura vasculaire est une lésion cutanée caractérisée par des <strong>macules ou papules érythémateuses</strong>, ne s'effaçant pas à la vitropression, dues à l'extravasation de sang dans le derme et l'épiderme. On parle de purpura vasculaire lorsque les lésions sont <strong>palpables</strong> ou <strong>nécrotiques</strong>, évoquant une inflammation des vaisseaux.</p>"}]};